import hashlib, json, re
from pathlib import Path

fixture_dir = Path("packages/teax-simkit/simkit/tests/evaluation/fixtures/sealed_package/package_live")

exclude_globs = ["contracts/package_contract.json", "**/__pycache__/**"]
runtime_output_globs = []

def glob_to_regex(pattern):
    out = []
    i, n = 0, len(pattern)
    while i < n:
        if pattern[i:i+3] == "**/":
            out.append("(?:.*/)?"); i += 3
        elif pattern[i:i+3] == "/**" and i + 3 == n:
            out.append("(?:/.*)?"); i += 3
        elif pattern[i] == "*":
            out.append("[^/]*"); i += 1
        elif pattern[i] == "?":
            out.append("[^/]"); i += 1
        else:
            out.append(re.escape(pattern[i])); i += 1
    return re.compile("^" + "".join(out) + "$")

def is_covered(rel_path, patterns):
    return not any(glob_to_regex(p).match(rel_path) for p in patterns)

patterns = exclude_globs + runtime_output_globs
artifact_hashes = {}
for path in sorted(fixture_dir.rglob("*")):
    if not path.is_file():
        continue
    rel = path.relative_to(fixture_dir).as_posix()
    if is_covered(rel, patterns):
        artifact_hashes[rel] = hashlib.sha256(path.read_bytes()).hexdigest()

executable_fingerprint = hashlib.sha256(
    "\n".join(f"{k}:{v}" for k, v in sorted(artifact_hashes.items())).encode("utf-8")
).hexdigest()

seal = {
    "package_name": "wi014_s4",
    "coverage_policy": {
        "exclude_globs": exclude_globs,
        "runtime_output_globs": runtime_output_globs,
    },
    "artifact_hashes": artifact_hashes,
    "executable_fingerprint": executable_fingerprint,
    "generator_version": "0.1.0",
    "runtime_contract_version": "1.0.0",
}

payload = json.dumps(seal, indent=2, sort_keys=True, ensure_ascii=True)
(fixture_dir / "contracts" / "package_contract.json").write_text(payload + "\n")
print(payload)
EOF

